  ('f2058371-ab92-5cb7-8c47-73c9b271ec49', 'Zomato', 'ZOM-3.1', '2026-04-01', '2026-09-07', 'partner_agreement_pdf', 0.990, 'Zomato Delivery Partner Agreement v3.1', 'ACTIVE', '[{"clause_id": "ZOM-3.1-C01", "clause_type": "BASE_RATE", "rule_id": "ZOM-3.1-R-BASE", "title": "Flat base pay per delivered order", "parameters": {"amount": 30.00, "unit": "per_order"}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C02", "clause_type": "PER_KM_RATE", "rule_id": "ZOM-3.1-R-DIST", "title": "Distance pay per km delivered", "parameters": {"rate_per_km": 6.00, "unit": "per_km"}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C03", "clause_type": "WAIT_TIME_RATE", "rule_id": "ZOM-3.1-R-WAIT", "title": "Restaurant wait-time compensation beyond free minutes (capped)", "parameters": {"free_minutes": 5, "rate_per_min": 1.00, "max_billable_minutes": 15}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C04", "clause_type": "INCENTIVE", "rule_id": "ZOM-3.1-R-PEAK", "title": "Peak-hour per-order incentive", "parameters": {"amount": 12.00, "windows": ["12:00-15:00", "19:00-22:00"], "basis": "order_timestamp_local"}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C05", "clause_type": "INCENTIVE", "rule_id": "ZOM-3.1-R-WKND", "title": "Weekend per-order incentive", "parameters": {"amount": 5.00, "days": ["SAT", "SUN"], "basis": "order_timestamp_local"}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C06", "clause_type": "INCENTIVE", "rule_id": "ZOM-3.1-R-DAILY", "title": "Daily order-count target bonus (paid once, on the order that reaches the target)", "parameters": {"threshold_orders": 7, "amount": 80.00, "scope": "platform_daily", "awarded_on": "threshold_crossing_order"}, "effective_from": "2026-04-01", "effective_to": "2026-09-07"}, {"clause_id": "ZOM-3.1-C07", "clause_type": "INCENTIVE", "rule_