-- =====================================================================
-- FairPay Engine  |  Partner: bobby  |  30-day CLEAN-BASELINE dataset
-- Target: Supabase / PostgreSQL 15+ (uses security_invoker views)
--
-- Zero anomalies by construction: every earning has exactly one
-- settlement, settlement = net, every line item cites a rule + clause.
-- No ground-truth / anomaly labels / audit findings are stored here.
--
-- NOTE: plain CREATE TABLE (not IF NOT EXISTS) so a clash with an
-- existing table of the same name fails loudly instead of silently
-- inserting into the wrong shape.
--
-- Optional reset (destructive - uncomment only if you own these tables):
-- DROP VIEW  IF EXISTS v_dataset_validation, v_daily_business_summary,
--                      v_business_cost_transactions, v_transaction_records;
-- DROP TABLE IF EXISTS legal_context, settlements, deductions, incentives,
--                      earnings, orders, work_sessions, platform_rules,
--                      contracts, vehicle_profiles, partner_platform_accounts,
--                      partners, dataset_meta CASCADE;
-- =====================================================================

CREATE TABLE dataset_meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

-- 1. partners  (mirrors PartnerProfile) -------------------------------
CREATE TABLE partners (
  partner_id          TEXT PRIMARY KEY,
  name                TEXT NOT NULL,
  phone               TEXT NOT NULL,
  vehicle_type        TEXT NOT NULL CHECK (vehicle_type IN ('MOTORCYCLE','SCOOTER','BICYCLE')),
  propulsion_type     TEXT NOT NULL CHECK (propulsion_type IN ('PETROL','EV')),
  petrol_per_km       NUMERIC(10,4) NOT NULL CHECK (petrol_per_km >= 0),
  zone                TEXT NOT NULL,
  platform_accounts   JSONB NOT NULL CHECK (jsonb_typeof(platform_accounts) = 'object'),
  bank_account_last4  CHAR(4) NOT NULL CHECK (bank_account_last4 ~ '^[0-9]{4}$'),
  active_since        DATE NOT NULL,
  CONSTRAINT ev_has_zero_petrol_cost CHECK (propulsion_type <> 'EV' OR petrol_per_km = 0)
);

CREATE TABLE partner_platform_accounts (
  partner_id    TEXT NOT NULL REFERENCES partners(partner_id),
  platform      TEXT NOT NULL CHECK (platform IN ('Zomato','Swiggy','UberEats')),
  account_id    TEXT NOT NULL,
  enrolled_from DATE NOT NULL,
  status        TEXT NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED')),
  PRIMARY KEY (partner_id, platform),
  UNIQUE (platform, account_id)
);

-- Vehicle / operating-cost basis. PETROL and EV are both supported;
-- the engine's petrol_per_km lives on partners (PartnerProfile).
CREATE TABLE vehicle_profiles (
  vehicle_id               TEXT PRIMARY KEY,
  partner_id               TEXT NOT NULL REFERENCES partners(partner_id),
  make_model               TEXT NOT NULL,
  vehicle_type             TEXT NOT NULL,
  propulsion_type          TEXT NOT NULL CHECK (propulsion_type IN ('PETROL','EV')),
  registration_year        INT,
  mileage_km_per_litre     NUMERIC(6,2),      -- PETROL only
  petrol_price_per_litre   NUMERIC(8,2),      -- PETROL only (fixed 110.00)
  petrol_per_km            NUMERIC(10,4) NOT NULL,
  ev_efficiency_wh_per_km  NUMERIC(8,2),      -- EV only
  ev_battery_kwh           NUMERIC(6,2),      -- EV only
  electricity_rate_per_kwh NUMERIC(8,2),      -- EV only
  effective_from           DATE NOT NULL,
  effective_to             DATE,
  CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT petrol_vehicle_cost CHECK (
    propulsion_type <> 'PETROL' OR (
      mileage_km_per_litre > 0 AND petrol_price_per_litre > 0
      AND petrol_per_km = ROUND(petrol_price_per_litre / mileage_km_per_litre, 4)
      AND ev_efficiency_wh_per_km IS NULL)),
  CONSTRAINT ev_vehicle_cost CHECK (
    propulsion_type <> 'EV' OR (
      petrol_per_km = 0 AND ev_efficiency_wh_per_km > 0 AND electricity_rate_per_kwh > 0
      AND mileage_km_per_litre IS NULL))
);

-- 4. contracts  (ContractVersion) --------------------------------------
CREATE TABLE contracts (
  contract_id    UUID PRIMARY KEY,
  platform       TEXT NOT NULL CHECK (platform IN ('Zomato','Swiggy','UberEats')),
  version_id     TEXT NOT NULL,
  effective_from DATE NOT NULL,
  effective_to   DATE,                         -- NULL = currently in force
  source         TEXT NOT NULL,
  confidence     NUMERIC(4,3) NOT NULL CHECK (confidence BETWEEN 0 AND 1),
  document_title TEXT NOT NULL,
  status         TEXT NOT NULL CHECK (status IN ('ACTIVE','SUPERSEDED','DRAFT')),
  clauses        JSONB NOT NULL CHECK (jsonb_typeof(clauses) = 'array'),
  UNIQUE (platform, version_id),
  CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

-- 5. platform_rules ----------------------------------------------------
CREATE TABLE platform_rules (
  rule_id          TEXT PRIMARY KEY,
  platform         TEXT NOT NULL CHECK (platform IN ('Zomato','Swiggy','UberEats')),
  rule_type        TEXT NOT NULL CHECK (rule_type IN (
                     'BASE_PAY','DISTANCE','WAIT','INCENTIVE_PEAK','INCENTIVE_WEEKEND',
                     'INCENTIVE_CAMPAIGN','BONUS_DAILY_TARGET','BONUS_WEEKLY_TARGET',
                     'DEDUCTION_FEE','DEDUCTION_PENALTY')),
  rule_version     TEXT NOT NULL,
  contract_version TEXT NOT NULL,
  clause_id        TEXT NOT NULL,
  effective_from   DATE NOT NULL,
  effective_to     DATE,
  parameters       JSONB NOT NULL,
  description      TEXT NOT NULL,
  status           TEXT NOT NULL CHECK (status IN ('ACTIVE','SUPERSEDED','DRAFT')),
  FOREIGN KEY (platform, contract_version) REFERENCES contracts(platform, version_id),
  CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

-- Work sessions: online windows used for online_hours / business_hours.
CREATE TABLE work_sessions (
  session_id              TEXT PRIMARY KEY,
  partner_id              TEXT NOT NULL REFERENCES partners(partner_id),
  session_date            DATE NOT NULL,
  session_type            TEXT NOT NULL CHECK (session_type IN ('LUNCH','DINNER')),
  online_start            TIMESTAMPTZ NOT NULL,
  online_end              TIMESTAMPTZ NOT NULL,
  travel_to_zone_minutes  INT NOT NULL CHECK (travel_to_zone_minutes >= 0),
  CHECK (online_end > online_start),
  UNIQUE (partner_id, session_date, session_type)
);

-- 2a. orders -----------------------------------------------------------
CREATE TABLE orders (
  order_id             TEXT PRIMARY KEY,
  partner_id           TEXT NOT NULL REFERENCES partners(partner_id),
  platform             TEXT NOT NULL,
  session_id           TEXT NOT NULL REFERENCES work_sessions(session_id),
  order_timestamp      TIMESTAMPTZ NOT NULL,   -- order accepted
  pickup_timestamp     TIMESTAMPTZ NOT NULL,   -- picked up from restaurant
  completed_timestamp  TIMESTAMPTZ NOT NULL,   -- delivered
  distance_km          NUMERIC(6,2) NOT NULL CHECK (distance_km > 0),
  duration_minutes     INT NOT NULL CHECK (duration_minutes > 0),   -- pickup -> drop
  wait_time_minutes    INT NOT NULL CHECK (wait_time_minutes >= 0), -- waiting at restaurant
  order_status         TEXT NOT NULL CHECK (order_status IN ('DELIVERED')),
  FOREIGN KEY (partner_id, platform) REFERENCES partner_platform_accounts(partner_id, platform),
  CONSTRAINT completed_eq_pickup_plus_duration
    CHECK (completed_timestamp = pickup_timestamp + duration_minutes * INTERVAL '1 minute'),
  CONSTRAINT pickup_covers_wait
    CHECK (pickup_timestamp >= order_timestamp + wait_time_minutes * INTERVAL '1 minute')
);

-- 2b. earnings (one per order; TransactionRecord core) ------------------
CREATE TABLE earnings (
  earning_id         TEXT PRIMARY KEY,
  transaction_id     TEXT NOT NULL UNIQUE,
  order_id           TEXT NOT NULL UNIQUE REFERENCES orders(order_id),
  partner_id         TEXT NOT NULL REFERENCES partners(partner_id),
  platform           TEXT NOT NULL,
  transaction_date   DATE NOT NULL,
  contract_version   TEXT NOT NULL,
  base_amount        NUMERIC(12,2) NOT NULL CHECK (base_amount >= 0),
  distance_amount    NUMERIC(12,2) NOT NULL CHECK (distance_amount >= 0),
  wait_amount        NUMERIC(12,2) NOT NULL CHECK (wait_amount >= 0),
  incentive_amount   NUMERIC(12,2) NOT NULL CHECK (incentive_amount >= 0),  -- per-order incentives
  bonus_amount       NUMERIC(12,2) NOT NULL CHECK (bonus_amount >= 0),      -- target bonuses
  gross_amount       NUMERIC(12,2) NOT NULL,
  deductions_total   NUMERIC(12,2) NOT NULL CHECK (deductions_total >= 0),
  net_amount         NUMERIC(12,2) NOT NULL CHECK (net_amount > 0),
  FOREIGN KEY (partner_id, platform) REFERENCES partner_platform_accounts(partner_id, platform),
  FOREIGN KEY (platform, contract_version) REFERENCES contracts(platform, version_id),
  CONSTRAINT gross_is_sum_of_components CHECK (
    gross_amount = base_amount + distance_amount + wait_amount + incentive_amount + bonus_amount),
  CONSTRAINT net_is_gross_minus_deductions CHECK (net_amount = gross_amount - deductions_total)
);

-- 6. incentives --------------------------------------------------------
CREATE TABLE incentives (
  incentive_id     UUID PRIMARY KEY,
  earning_id       TEXT NOT NULL REFERENCES earnings(earning_id),
  partner_id       TEXT NOT NULL REFERENCES partners(partner_id),
  platform         TEXT NOT NULL,
  rule_id          TEXT NOT NULL REFERENCES platform_rules(rule_id),
  name             TEXT NOT NULL,
  incentive_type   TEXT NOT NULL CHECK (incentive_type IN
                     ('peak_hour','weekend','campaign','daily_target','weekly_target')),
  kind             TEXT NOT NULL CHECK (kind IN ('incentive','bonus')),
  amount           NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  policy_reference TEXT NOT NULL,
  UNIQUE (earning_id, rule_id),
  CHECK ((kind = 'bonus') = (incentive_type IN ('daily_target','weekly_target')))
);

-- 7. deductions --------------------------------------------------------
CREATE TABLE deductions (
  deduction_id     UUID PRIMARY KEY,
  earning_id       TEXT NOT NULL REFERENCES earnings(earning_id),
  partner_id       TEXT NOT NULL REFERENCES partners(partner_id),
  platform         TEXT NOT NULL,
  rule_id          TEXT NOT NULL REFERENCES platform_rules(rule_id),
  name             TEXT NOT NULL,
  amount           NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  category         TEXT NOT NULL CHECK (category IN ('fee','penalty','adjustment')),
  policy_reference TEXT NOT NULL,
  UNIQUE (earning_id, rule_id)
);

-- 3. settlements -------------------------------------------------------
CREATE TABLE settlements (
  settlement_id         TEXT PRIMARY KEY,
  earning_id            TEXT NOT NULL UNIQUE REFERENCES earnings(earning_id),
  transaction_id        TEXT NOT NULL UNIQUE REFERENCES earnings(transaction_id),
  partner_id            TEXT NOT NULL REFERENCES partners(partner_id),
  platform              TEXT NOT NULL,
  settlement_date       DATE NOT NULL,
  settlement_timestamp  TIMESTAMPTZ NOT NULL,
  amount_paid           NUMERIC(12,2) NOT NULL CHECK (amount_paid > 0),
  payout_channel        TEXT NOT NULL CHECK (payout_channel IN ('BANK_TRANSFER','UPI','WALLET')),
  bank_account_last4    CHAR(4) NOT NULL,
  payout_reference      TEXT NOT NULL UNIQUE,
  CONSTRAINT settlement_date_matches_ts
    CHECK (settlement_date = (settlement_timestamp AT TIME ZONE 'Asia/Kolkata')::date)
);

-- Legal / classification facts for Layer 2 (facts only, no conclusions)
CREATE TABLE legal_context (
  legal_id               TEXT PRIMARY KEY,
  partner_id             TEXT REFERENCES partners(partner_id),  -- NULL = general rule
  platform               TEXT,
  jurisdiction           TEXT NOT NULL,
  worker_classification  TEXT,
  statute                TEXT NOT NULL,
  section                TEXT NOT NULL,
  applicability          TEXT NOT NULL,
  effective_from         DATE NOT NULL,
  effective_to           DATE,
  rule_version           TEXT NOT NULL,
  status                 TEXT NOT NULL CHECK (status IN ('IN_FORCE','PENDING_NOTIFICATION','REPEALED','DRAFT')),
  source_reference       TEXT NOT NULL,
  citation_verified      BOOLEAN NOT NULL,
  attributes             JSONB NOT NULL DEFAULT '{}'::jsonb
);

-- Indexes (api.py queries by partner_id + date) -------------------------
CREATE INDEX idx_orders_partner_completed   ON orders (partner_id, completed_timestamp);
CREATE INDEX idx_orders_session             ON orders (session_id);
CREATE INDEX idx_earnings_partner_date      ON earnings (partner_id, transaction_date);
CREATE INDEX idx_earnings_partner_plat_date ON earnings (partner_id, platform, transaction_date);
CREATE INDEX idx_incentives_earning         ON incentives (earning_id);
CREATE INDEX idx_deductions_earning         ON deductions (earning_id);
CREATE INDEX idx_settlements_partner_date   ON settlements (partner_id, settlement_date);
CREATE INDEX idx_sessions_partner_date      ON work_sessions (partner_id, session_date);
CREATE INDEX idx_rules_lookup               ON platform_rules (platform, rule_type, effective_from);
CREATE INDEX idx_contracts_lookup           ON contracts (platform, effective_from);
CREATE INDEX idx_legal_partner              ON legal_context (partner_id);

-- =====================================================================
-- API-facing views
-- =====================================================================

-- One row per TransactionRecord; deductions[]/incentives[] as JSONB arrays.
-- gross_amount INCLUDES incentives + bonuses; net_amount = gross - deductions.
CREATE VIEW v_transaction_records WITH (security_invoker = true) AS
SELECT
  e.transaction_id, e.partner_id, e.platform, e.transaction_date,
  e.gross_amount, e.net_amount,
  o.distance_km, o.duration_minutes, o.wait_time_minutes,
  e.contract_version,
  COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'name', d.name, 'amount', d.amount,
              'policy_reference', d.policy_reference, 'category', d.category) ORDER BY d.name)
            FROM deductions d WHERE d.earning_id = e.earning_id), '[]'::jsonb) AS deductions,
  COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'name', i.name, 'amount', i.amount, 'type', i.incentive_type, 'kind', i.kind,
              'policy_reference', i.policy_reference) ORDER BY i.name)
            FROM incentives i WHERE i.earning_id = e.earning_id), '[]'::jsonb) AS incentives,
  e.order_id, e.earning_id, s.settlement_id,
  o.order_timestamp, o.completed_timestamp,
  s.settlement_timestamp, s.settlement_date, s.amount_paid
FROM earnings e
JOIN orders o      ON o.order_id = e.order_id
JOIN settlements s ON s.earning_id = e.earning_id;

-- Per-transaction operating cost. PETROL: distance * petrol_per_km.
-- EV: petrol_cost = 0, energy_cost = distance * Wh/km / 1000 * Rs/kWh.
CREATE VIEW v_business_cost_transactions WITH (security_invoker = true) AS
SELECT
  e.transaction_id, e.partner_id, e.platform, e.transaction_date,
  o.distance_km, o.duration_minutes, o.wait_time_minutes,
  p.vehicle_type, p.propulsion_type, p.petrol_per_km,
  CASE WHEN p.propulsion_type = 'PETROL' THEN o.distance_km * p.petrol_per_km ELSE 0 END AS petrol_cost,
  CASE WHEN p.propulsion_type = 'EV'
       THEN o.distance_km * vp.ev_efficiency_wh_per_km / 1000 * vp.electricity_rate_per_kwh
       ELSE 0 END AS energy_cost,
  o.duration_minutes / 60.0                          AS duration_hours,
  (o.duration_minutes + o.wait_time_minutes) / 60.0  AS active_hours,
  e.net_amount AS income_received
FROM earnings e
JOIN orders o   ON o.order_id = e.order_id
JOIN partners p ON p.partner_id = e.partner_id
JOIN vehicle_profiles vp ON vp.partner_id = e.partner_id
 AND e.transaction_date >= vp.effective_from
 AND (vp.effective_to IS NULL OR e.transaction_date <= vp.effective_to);

-- Per-day roll-up incl. online / business hours and hourly rates.
--   active_hours   = SUM(duration + wait) / 60
--   online_hours   = SUM(online session length) / 60
--   business_hours = online_hours + SUM(travel_to_zone_minutes) / 60
CREATE VIEW v_daily_business_summary WITH (security_invoker = true) AS
WITH t AS (
  SELECT partner_id, transaction_date AS day, COUNT(*) AS orders,
         SUM(distance_km) AS distance_km, SUM(petrol_cost) AS petrol_cost, SUM(energy_cost) AS energy_cost,
         SUM(duration_hours) AS duration_hours, SUM(active_hours) AS active_hours,
         SUM(income_received) AS income_received
  FROM v_business_cost_transactions GROUP BY partner_id, transaction_date
), s AS (
  SELECT partner_id, session_date AS day,
         SUM(EXTRACT(EPOCH FROM (online_end - online_start))) / 3600.0 AS online_hours,
         SUM(travel_to_zone_minutes) / 60.0 AS travel_hours
  FROM work_sessions GROUP BY partner_id, session_date
)
SELECT t.partner_id, t.day, t.orders, t.distance_km, t.petrol_cost, t.energy_cost,
       t.duration_hours, t.active_hours, s.online_hours, s.online_hours + s.travel_hours AS business_hours,
       t.income_received,
       t.income_received - t.petrol_cost - t.energy_cost AS net_after_operating_cost,
       t.income_received / NULLIF(t.active_hours, 0)                       AS active_hourly_rate,
       t.income_received / NULLIF(s.online_hours, 0)                       AS online_hourly_rate,
       t.income_received / NULLIF(s.online_hours + s.travel_hours, 0)      AS business_hourly_rate
FROM t JOIN s USING (partner_id, day);

-- Self-check: every row must show violations = 0 for a clean baseline.
CREATE VIEW v_dataset_validation WITH (security_invoker = true) AS
WITH m AS (
  SELECT (SELECT value FROM dataset_meta WHERE key = 'window_start')::timestamptz AS w0,
         (SELECT value FROM dataset_meta WHERE key = 'window_end')::timestamptz   AS w1,
         (SELECT value FROM dataset_meta WHERE key = 'settlement_tolerance_days')::int AS tol
)
SELECT 'earnings_without_settlement' AS check_name, COUNT(*) AS violations
  FROM earnings e WHERE NOT EXISTS (SELECT 1 FROM settlements s WHERE s.earning_id = e.earning_id)
UNION ALL SELECT 'settlements_without_earning', COUNT(*)
  FROM settlements s WHERE NOT EXISTS (SELECT 1 FROM earnings e WHERE e.earning_id = s.earning_id)
UNION ALL SELECT 'duplicate_settlements', COUNT(*) FROM (
  SELECT earning_id FROM settlements GROUP BY earning_id HAVING COUNT(*) > 1) x
UNION ALL SELECT 'payment_difference (amount_paid <> net_amount)', COUNT(*)
  FROM earnings e JOIN settlements s ON s.earning_id = e.earning_id WHERE s.amount_paid <> e.net_amount
UNION ALL SELECT 'settlement_partner_or_platform_mismatch', COUNT(*)
  FROM earnings e JOIN settlements s ON s.earning_id = e.earning_id
  WHERE s.partner_id <> e.partner_id OR s.platform <> e.platform OR s.transaction_id <> e.transaction_id
UNION ALL SELECT 'settlement_before_completion', COUNT(*)
  FROM earnings e JOIN orders o ON o.order_id = e.order_id JOIN settlements s ON s.earning_id = e.earning_id
  WHERE s.settlement_timestamp <= o.completed_timestamp
UNION ALL SELECT 'settlement_outside_tolerance', COUNT(*)
  FROM earnings e JOIN settlements s ON s.earning_id = e.earning_id, m
  WHERE s.settlement_date - e.transaction_date > m.tol OR s.settlement_date < e.transaction_date
UNION ALL SELECT 'earning_partner_platform_differs_from_order', COUNT(*)
  FROM earnings e JOIN orders o ON o.order_id = e.order_id
  WHERE o.partner_id <> e.partner_id OR o.platform <> e.platform
UNION ALL SELECT 'transaction_date_differs_from_completed_date', COUNT(*)
  FROM earnings e JOIN orders o ON o.order_id = e.order_id
  WHERE (o.completed_timestamp AT TIME ZONE 'Asia/Kolkata')::date <> e.transaction_date
UNION ALL SELECT 'contract_not_effective_on_transaction_date', COUNT(*)
  FROM earnings e JOIN contracts c ON c.platform = e.platform AND c.version_id = e.contract_version
  WHERE e.transaction_date < c.effective_from OR (c.effective_to IS NOT NULL AND e.transaction_date > c.effective_to)
UNION ALL SELECT 'overlapping_contract_versions', COUNT(*)
  FROM contracts a JOIN contracts b ON a.platform = b.platform AND a.contract_id < b.contract_id
  WHERE a.effective_from <= COALESCE(b.effective_to, DATE '9999-12-31')
    AND b.effective_from <= COALESCE(a.effective_to, DATE '9999-12-31')
UNION ALL SELECT 'incentive_rule_not_effective_or_wrong_contract', COUNT(*)
  FROM incentives i JOIN earnings e ON e.earning_id = i.earning_id JOIN platform_rules r ON r.rule_id = i.rule_id
  WHERE e.transaction_date < r.effective_from OR (r.effective_to IS NOT NULL AND e.transaction_date > r.effective_to)
     OR r.contract_version <> e.contract_version OR r.platform <> e.platform
UNION ALL SELECT 'deduction_rule_not_effective_or_wrong_contract', COUNT(*)
  FROM deductions d JOIN earnings e ON e.earning_id = d.earning_id JOIN platform_rules r ON r.rule_id = d.rule_id
  WHERE e.transaction_date < r.effective_from OR (r.effective_to IS NOT NULL AND e.transaction_date > r.effective_to)
     OR r.contract_version <> e.contract_version OR r.platform <> e.platform
UNION ALL SELECT 'incentive_total_mismatch', COUNT(*)
  FROM earnings e WHERE e.incentive_amount <>
    COALESCE((SELECT SUM(amount) FROM incentives i WHERE i.earning_id = e.earning_id AND i.kind = 'incentive'), 0)
UNION ALL SELECT 'bonus_total_mismatch', COUNT(*)
  FROM earnings e WHERE e.bonus_amount <>
    COALESCE((SELECT SUM(amount) FROM incentives i WHERE i.earning_id = e.earning_id AND i.kind = 'bonus'), 0)
UNION ALL SELECT 'deduction_total_mismatch', COUNT(*)
  FROM earnings e WHERE e.deductions_total <>
    COALESCE((SELECT SUM(amount) FROM deductions d WHERE d.earning_id = e.earning_id), 0)
UNION ALL SELECT 'order_outside_online_session', COUNT(*)
  FROM orders o JOIN work_sessions w ON w.session_id = o.session_id
  WHERE o.order_timestamp < w.online_start OR o.completed_timestamp > w.online_end
UNION ALL SELECT 'timestamps_outside_30_day_window', COUNT(*)
  FROM (SELECT completed_timestamp AS ts FROM orders UNION ALL SELECT order_timestamp FROM orders
        UNION ALL SELECT settlement_timestamp FROM settlements UNION ALL SELECT online_start FROM work_sessions
        UNION ALL SELECT online_end FROM work_sessions) x, m
  WHERE x.ts < m.w0 OR x.ts > m.w1
UNION ALL SELECT 'rows_dated_today_or_later', COUNT(*)
  FROM settlements s, m WHERE s.settlement_timestamp > m.w1
UNION ALL SELECT 'non_bobby_partner_rows', (
    (SELECT COUNT(*) FROM orders WHERE partner_id <> 'bobby') + (SELECT COUNT(*) FROM earnings WHERE partner_id <> 'bobby')
  + (SELECT COUNT(*) FROM settlements WHERE partner_id <> 'bobby'))
UNION ALL SELECT 'duplicate_payout_references', COUNT(*) FROM (
  SELECT payout_reference FROM settlements GROUP BY payout_reference HAVING COUNT(*) > 1) x
UNION ALL SELECT 'distinct_days_with_data_gt_30', GREATEST(0, (SELECT COUNT(DISTINCT transaction_date) FROM earnings) - 30)
UNION ALL SELECT 'petrol_per_km_differs_from_110_div_mileage', COUNT(*)
  FROM partners p JOIN vehicle_profiles v ON v.partner_id = p.partner_id
  WHERE p.propulsion_type = 'PETROL'
    AND (p.petrol_per_km <> ROUND(110.00 / v.mileage_km_per_litre, 4) OR v.petrol_price_per_litre <> 110.00);


